#!/usr/bin/env node
/**
 * Reproducible harvest of the USGS Historical Topographic Map Collection
 * (HTMC) through the documented The National Map Access API.
 *
 * Source: U.S. Geological Survey, `datasets=Historical Topographic Maps`.
 * Rights: USGS-produced works are U.S. Government works and are in the public
 * domain in the United States (17 U.S.C. §105); the USGS FAQ is cited in the
 * provider registry and on the harvest selection. The scan/product URLs still
 * credit USGS.
 *
 * The HTMC is a very large product set (186,061 products on 2026-10-20), so a
 * run samples whole API pages across the ordered set instead of taking only
 * the first page. Cached pages make a run resumable; already-imported records
 * are preserved when the shard is rewritten, so a later, wider run only adds.
 *
 * Usage:
 *   node scripts/harvest-usgs.mjs                  # sample ~6,000 products
 *   node scripts/harvest-usgs.mjs --target 12000   # ten wider sample pages
 *   node scripts/harvest-usgs.mjs --refresh        # refetch API pages
 *   node scripts/harvest-usgs.mjs --no-write       # report only
 */
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readCore, shardPath, shardUrl, writeShard } from './catalogue.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/usgs');
const REFRESH = has('refresh');
const WRITE = !has('no-write');
const TARGET = Math.max(1, Math.min(60000, Number(value('target', '6000')) || 6000));
const PAGE_SIZE = Math.max(1, Math.min(1000, Number(value('page-size', '1000')) || 1000));
const CONCURRENCY = Math.max(1, Math.min(4, Number(value('concurrency', '2')) || 2));
const TIMEOUT = Math.max(15000, Number(value('timeout', '120000')) || 120000);
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)';
const API = 'https://tnmaccess.nationalmap.gov/api/v1/products';
const DATASET = 'Historical Topographic Maps';
const TERMS = 'https://www.usgs.gov/faqs/are-usgs-topographic-maps-copyrighted';
const RETRIEVED = new Date().toISOString().slice(0, 10);
const shard = shardUrl('usgs');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function apiUrl(offset, max = PAGE_SIZE) {
  const url = new URL(API);
  url.searchParams.set('datasets', DATASET);
  url.searchParams.set('max', String(max));
  url.searchParams.set('offset', String(offset));
  url.searchParams.set('outputFormat', 'JSON');
  return url.href;
}

async function fetchJson(url, attempts = 4) {
  let last;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const res = await fetch(url, {
        headers: { accept: 'application/json', 'user-agent': UA },
        signal: AbortSignal.timeout(TIMEOUT),
      });
      const body = await res.text();
      if (res.ok && body.trim().startsWith('{')) return JSON.parse(body);
      last = new Error(`${res.status} ${url} (${body.slice(0, 80)})`);
      if (res.status !== 429 && res.status < 500) break;
    } catch (error) {
      last = error;
    }
    await sleep(1200 * attempt + Math.floor(Math.random() * 500));
  }
  throw last;
}

async function cachedPage(offset) {
  const path = resolve(CACHE, `offset-${offset}-max-${PAGE_SIZE}.json`);
  if (!REFRESH) {
    try {
      return JSON.parse(await readFile(path, 'utf8'));
    } catch {}
  }
  const body = await fetchJson(apiUrl(offset));
  await mkdir(dirname(path), { recursive: true });
  const temp = `${path}.tmp-${process.pid}`;
  await writeFile(temp, JSON.stringify(body));
  await rename(temp, path);
  return body;
}

/** Publication year, kept separate from the map's depicted period. */
export function publicationYear(value) {
  const match = String(value ?? '').match(/\b(1[4-9][0-9]{2}|20[0-9]{2})\b/);
  return match ? Number(match[1]) : null;
}

/** A complete, plausible WGS84 product footprint, never guessed from a title. */
export function footprintOf(value) {
  if (!value) return null;
  const west = Number(value.minX ?? value.west);
  const east = Number(value.maxX ?? value.east);
  const south = Number(value.minY ?? value.south);
  const north = Number(value.maxY ?? value.north);
  return [west, east, south, north].every(Number.isFinite) &&
    west >= -180 &&
    east <= 180 &&
    south >= -90 &&
    north <= 90 &&
    west < east &&
    south < north
    ? { west, east, south, north }
    : null;
}

const ALLOWED_DOWNLOAD_HOSTS = new Set(['prd-tnm.s3.amazonaws.com', 'ngmdb.usgs.gov']);

function downloadUrl(value) {
  try {
    const url = new URL(value);
    return url.protocol === 'https:' && ALLOWED_DOWNLOAD_HOSTS.has(url.hostname) ? url.href : null;
  } catch {
    return null;
  }
}

function metaUrlOf(item) {
  try {
    const url = new URL(item.metaUrl ?? '');
    return url.protocol === 'https:' && url.hostname === 'www.sciencebase.gov' ? url.href : null;
  } catch {
    return null;
  }
}

/**
 * Convert one TNM product to a catalogue record. Returns null for a product
 * without a stable identity, title, date, public footprint, preview or a
 * documented USGS download. The HTML metadata page is cited, not cloned.
 */
export function recordOf(item) {
  if (!item || typeof item !== 'object') return null;
  const sourceId = String(item.sourceId ?? '').trim();
  const title = String(item.title ?? '').replace(/\s+/g, ' ').trim();
  const meta = metaUrlOf(item);
  const extent = footprintOf(item.boundingBox);
  const year = publicationYear(item.publicationDate);
  if (!/^[a-zA-Z0-9]+$/.test(sourceId) || sourceId.length > 80) return null;
  if (!title || !meta || !extent || year == null) return null;
  const downloads = [];
  const seen = new Set();
  const add = (label, raw) => {
    const url = downloadUrl(raw);
    if (!url || seen.has(url)) return;
    seen.add(url);
    downloads.push({ label, url });
  };
  for (const [label, raw] of Object.entries(item.urls ?? {})) add(label, raw);
  add('Product download', item.downloadURL);
  add('Georeferenced GeoTIFF', item.downloadURLRaster);
  if (downloads.length === 0) return null;
  const thumbnail = downloadUrl(item.previewGraphicURL);
  if (!thumbnail) return null;
  const record = {
    id: `usgs:${sourceId}`,
    title,
    yearStart: year,
    yearEnd: year,
    depictedYearStart: null,
    depictedYearEnd: null,
    creators: ['U.S. Geological Survey'],
    providerId: 'usgs',
    institution: 'U.S. Geological Survey',
    rights:
      'USGS-produced work: public domain in the United States (17 U.S.C. 105). Retain the USGS source credit.',
    rightsBasis: 'usgs-public-domain',
    recordUrl: meta,
    thumbnail,
    type: 'map',
    collection: 'Historical Topographic Maps — USGS',
    dateDisplay: String(item.publicationDate ?? ''),
    extent,
    geo: { lat: (extent.south + extent.north) / 2, lon: (extent.west + extent.east) / 2 },
    geoNote:
      'Product footprint published by the USGS Historical Topographic Map Collection. It is a discovery extent, not a scan alignment; the GeoTIFF carries the georeferencing.',
    metadataSource: meta,
    downloads,
    format: String(item.format ?? ''),
    extentLabel: String(item.extent ?? ''),
    sourceName: String(item.sourceName ?? 'USGS'),
    metadataTerms: TERMS,
  };
  if (item.moreInfo) record.description = String(item.moreInfo).replace(/\s+/g, ' ').trim();
  return record;
}

function sampleOffsets(total, target, max) {
  const pages = Math.max(1, Math.ceil(target / max));
  const offsets = [];
  for (let i = 0; i < pages; i++) {
    const offset = Math.min(Math.max(0, total - 1), Math.floor((i * total) / pages));
    if (!offsets.includes(offset)) offsets.push(offset);
  }
  return offsets;
}

async function pool(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  async function worker() {
    while (true) {
      const i = next++;
      if (i >= items.length) return;
      out[i] = await fn(items[i], i);
      await sleep(80);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

async function probe(url, accept = '*/*') {
  try {
    const res = await fetch(url, {
      headers: { accept, 'user-agent': UA, range: 'bytes=0-2047' },
      signal: AbortSignal.timeout(45000),
    });
    await res.body?.cancel?.();
    return { status: res.status, type: res.headers.get('content-type') ?? '' };
  } catch (error) {
    return { status: 0, error: String(error.message) };
  }
}

async function verify(records) {
  const sample = [];
  const step = Math.max(1, Math.floor(records.length / 20));
  for (let i = 0; i < records.length && sample.length < 20; i += step) sample.push(records[i]);
  const results = await pool(sample, 3, async (record) => {
    const thumb = await probe(record.thumbnail, 'image/jpeg');
    const raster = record.downloads.find((d) => /GeoTIFF/i.test(d.label));
    const rasterProbe = raster ? await probe(raster.url, 'image/tiff,application/octet-stream') : null;
    return {
      id: record.id,
      thumbnail: thumb.status,
      thumbnailType: thumb.type,
      raster: rasterProbe?.status ?? null,
      rasterType: rasterProbe?.type ?? null,
    };
  });
  return {
    retrieved: RETRIEVED,
    sample: results.length,
    thumbnailOk: results.filter((r) => r.thumbnail === 206 || r.thumbnail === 200).length,
    rasterOk: results.filter((r) => r.raster === 206 || r.raster === 200).length,
    examples: results.slice(0, 5),
  };
}

async function existingShardRecords() {
  try {
    const doc = JSON.parse(await readFile(shardPath(OUT, shard), 'utf8'));
    return Array.isArray(doc.records) ? doc.records : [];
  } catch {
    return [];
  }
}

async function main() {
  const first = await cachedPage(0);
  const total = Number(first.total) || 0;
  if (!total) throw new Error('USGS API did not state a product total; leaving the catalogue unchanged.');
  const offsets = sampleOffsets(total, TARGET, PAGE_SIZE);
  console.log(`USGS HTMC: ${total} products; sampling ${offsets.length} page(s): ${offsets.join(', ')}`);

  const pages = [];
  let next = 0;
  async function worker() {
    while (true) {
      const i = next++;
      if (i >= offsets.length) return;
      pages[i] = await cachedPage(offsets[i]);
      if (i % 5 === 0) console.log(`cached sample page ${i + 1}/${offsets.length} at offset ${offsets[i]}`);
      await sleep(150);
    }
  }
  await Promise.all(Array.from({ length: CONCURRENCY }, worker));

  const seen = new Set();
  const records = [];
  let examined = 0;
  const rejected = {};
  for (const page of pages) {
    for (const item of page.items ?? []) {
      examined += 1;
      const record = recordOf(item);
      if (!record) {
        const reason = !item?.title
          ? 'missing title'
          : !item?.sourceId
            ? 'missing sourceId'
            : !footprintOf(item.boundingBox)
              ? 'missing or invalid product footprint'
              : publicationYear(item.publicationDate) == null
                ? 'missing publication year'
                : 'metadata gate (preview, download or metadata URL)';
        rejected[reason] = (rejected[reason] || 0) + 1;
        continue;
      }
      if (seen.has(record.id)) continue;
      seen.add(record.id);
      records.push(record);
    }
  }
  if (records.length === 0) throw new Error('No eligible USGS products; leaving the catalogue unchanged.');

  const prior = await existingShardRecords();
  const priorIds = new Set(prior.map((record) => record.id));
  const added = records.filter((record) => !priorIds.has(record.id));
  const merged = [...prior, ...added].sort(
    (a, b) => (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) || a.id.localeCompare(b.id),
  );
  const verification = await verify(merged);
  console.log(`Eligible products in this sample: ${records.length}; new: ${added.length}; shard total: ${merged.length}`);
  console.log('Withheld:', rejected);
  console.log('Verification sample:', verification);

  const recordsPath = resolve(OUT, 'records.json');
  const sourcesPath = resolve(OUT, 'sources.json');
  const core = await readCore(OUT);
  const sourcesDoc = JSON.parse(await readFile(sourcesPath, 'utf8'));
  const generatedAt = new Date().toISOString();

  core.shards = [...new Set([...(core.shards ?? []), shard])].sort();
  core.records = (core.records ?? []).filter((record) => record.providerId !== 'usgs');
  core.generatedAt = generatedAt;
  core.retrieved = RETRIEVED;
  core.method = `${core.method ? core.method + ' ' : ''}USGS Historical Topographic Map Collection products are imported from the documented The National Map Access API, with their published footprint, preview and GeoTIFF/GeoPDF links, into ${shard}.`;
  core.selection ??= {};
  const previous = core.selection['usgs:htmc'] ?? {};
  core.selection['usgs:htmc'] = {
    considered: examined,
    kept: merged.length,
    addedThisRun: added.length,
    shard,
    rightsBasis: { 'usgs-public-domain': merged.length },
    withheld: rejected,
    api: {
      endpoint: API,
      query: `datasets=${encodeURIComponent(DATASET)}&max=${PAGE_SIZE}&offset={offset}&outputFormat=JSON`,
      total,
      offsets,
    },
    rule:
      'Products of the USGS Historical Topographic Map Collection with a stable sourceId, a verbatim title, a publication date, a complete published product footprint, a preview image and at least one USGS-hosted GeoTIFF/GeoPDF download. These are U.S. Government works in the public domain; no third-party map was admitted. A sample of whole API pages is read across the ordered set so early states/scales do not crowd out the rest; prior shard records are preserved on rerun.',
    runs: [...(previous.runs ?? []), { retrieved: RETRIEVED, offsets, examined, kept: records.length, added: added.length }].slice(-12),
    verification,
  };

  const provider = {
    id: 'usgs',
    name: 'USGS Historical Topographic Maps',
    operator: 'U.S. Geological Survey, The National Map',
    homepage: 'https://ngmdb.usgs.gov/topoview/',
    home: 'https://www.usgs.gov/programs/national-geospatial-program/historical-topographic-maps-preserving-past',
    institutions: ['U.S. Geological Survey'],
    rights:
      'USGS-produced historical topographic maps are U.S. Government works in the public domain in the United States (17 U.S.C. 105). The product record keeps the USGS source credit; no third-party map is included.',
    rightsBasis: 'usgs-public-domain',
    attribution: 'U.S. Geological Survey, The National Map — Historical Topographic Map Collection',
    retrieved: RETRIEVED,
    api: {
      catalogue: `${API}?datasets=Historical+Topographic+Maps&max={max}&offset={offset}&outputFormat=JSON`,
      terms: TERMS,
      viewer: 'https://ngmdb.usgs.gov/topoview/',
      docs: 'https://tnmaccess.nationalmap.gov/api/v1/docs',
    },
    apiHosts: ['tnmaccess.nationalmap.gov', 'www.sciencebase.gov', 'prd-tnm.s3.amazonaws.com', 'ngmdb.usgs.gov'],
    method:
      'Documented The National Map Access API, dataset Historical Topographic Maps. Whole pages are sampled across the ordered set (max 1000, offsets recorded), cached and resumable; every product must have a title, date, footprint, preview and USGS-hosted GeoTIFF/GeoPDF. No geography or decade cap beyond the sampled page coverage itself.',
    collections: [
      {
        id: 'htmc',
        name: 'Historical Topographic Map Collection',
        discovery: `${API}?datasets=Historical+Topographic+Maps&max=25&offset=0&outputFormat=JSON`,
      },
    ],
    verification,
  };

  sourcesDoc.providers = [...sourcesDoc.providers.filter((source) => source.id !== 'usgs'), provider];
  sourcesDoc.generatedAt = generatedAt;

  const shardDoc = {
    generatedAt,
    retrieved: RETRIEVED,
    providerId: 'usgs',
    method: core.selection['usgs:htmc'].rule,
    selection: core.selection['usgs:htmc'],
    records: merged,
  };
  const coreBytes = Buffer.byteLength(JSON.stringify(core));
  const shardBytes = Buffer.byteLength(JSON.stringify(shardDoc));
  console.log(
    `Catalogue would be ${core.records.length} core + ${merged.length} USGS records; ` +
      `core ${(coreBytes / 1024 / 1024).toFixed(2)} MiB, shard ${(shardBytes / 1024 / 1024).toFixed(2)} MiB`,
  );
  if (coreBytes > 24 * 1024 * 1024 || shardBytes > 24 * 1024 * 1024) {
    throw new Error('A catalogue asset exceeds 24 MiB; split it before writing.');
  }
  if (WRITE) {
    await writeShard(OUT, shard, merged, {
      generatedAt,
      retrieved: RETRIEVED,
      providerId: 'usgs',
      method: core.selection['usgs:htmc'].rule,
      selection: core.selection['usgs:htmc'],
    });
    await writeFile(recordsPath, JSON.stringify(core) + '\n');
    await writeFile(sourcesPath, JSON.stringify(sourcesDoc, null, 2) + '\n');
    console.log('Wrote', OUT, 'and', shard);
  }
}

if (process.argv[1] && import.meta.url === new URL(`file://${resolve(process.argv[1])}`).href) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}

