/**
 * USGS HTMC importer gate.
 *
 * The HTMC is a public-domain U.S. Government product set, but a catalogue
 * record still needs a stable identity, a verbatim title, a publication date,
 * a complete published footprint, a preview and a USGS-hosted GeoTIFF/GeoPDF.
 * These tests pin that contract and make sure a title, a bbox or a public
 * landing page alone never becomes an image record.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { footprintOf, publicationYear, recordOf } from '../scripts/harvest-usgs.mjs';

const item = {
  title: 'USGS 1:62500-scale Quadrangle for Chesterfield, MA 1886',
  sourceId: '5e6779b1e4b01d50925c157b',
  metaUrl: 'https://www.sciencebase.gov/catalog/item/5e6779b1e4b01d50925c157b',
  publicationDate: '1886-01-01',
  format: 'GeoPDF, GeoTIFF',
  extent: '15 x 15 minute',
  downloadURL: 'https://prd-tnm.s3.amazonaws.com/StagedProducts/Maps/HistoricalTopo/PDF/MA/62500/MA_Chesterfield_462903_1886_62500_geo.pdf',
  previewGraphicURL:
    'https://prd-tnm.s3.amazonaws.com/StagedProducts/Maps/HistoricalTopo/PDF/MA/62500/MA_Chesterfield_462903_1886_62500_tn.jpg',
  urls: {
    GeoPDF:
      'https://prd-tnm.s3.amazonaws.com/StagedProducts/Maps/HistoricalTopo/PDF/MA/62500/MA_Chesterfield_462903_1886_62500_geo.pdf',
    GeoTIFF:
      'https://prd-tnm.s3.amazonaws.com/StagedProducts/Maps/HistoricalTopo/GeoTIFF/MA/MA_Chesterfield_462903_1886_62500_geo.tif',
  },
  boundingBox: { minX: -73, maxX: -72.75, minY: 42.25, maxY: 42.5 },
};

test('a USGS HTMC product keeps its own identity, title, date and published footprint', () => {
  const record = recordOf(item);
  assert.equal(record.id, 'usgs:5e6779b1e4b01d50925c157b');
  assert.equal(record.providerId, 'usgs');
  assert.equal(record.title, item.title);
  assert.equal(record.yearStart, 1886);
  assert.equal(record.yearEnd, 1886);
  assert.deepEqual(record.extent, { west: -73, east: -72.75, south: 42.25, north: 42.5 });
  assert.deepEqual(record.geo, { lat: 42.375, lon: -72.875 });
  assert.match(record.rights, /public domain/i);
  assert.match(record.geoNote, /not a scan alignment/i);
  assert.equal(record.thumbnail, item.previewGraphicURL);
  assert.deepEqual(
    record.downloads.map((download) => download.label),
    ['GeoPDF', 'GeoTIFF'],
  );
  assert.equal(record.downloads[1].url, item.urls.GeoTIFF);
});

test('the depicted period stays unknown rather than copying the publication year', () => {
  const record = recordOf(item);
  assert.equal(record.depictedYearStart, null);
  assert.equal(record.depictedYearEnd, null);
});

test('a product without a stable identity, title, date, footprint or preview is withheld', () => {
  for (const patch of [
    { sourceId: '' },
    { title: '' },
    { publicationDate: '' },
    { boundingBox: null },
    { previewGraphicURL: '' },
    { metaUrl: 'https://example.org/item/1' },
  ]) {
    assert.equal(recordOf({ ...item, ...patch }), null, JSON.stringify(patch));
  }
});

test('a download or preview outside the documented USGS hosts never becomes a catalogue URL', () => {
  assert.equal(recordOf({ ...item, urls: {}, downloadURL: 'https://example.org/map.tif' }), null);
  assert.equal(recordOf({ ...item, previewGraphicURL: 'https://example.org/preview.jpg' }), null);
  const record = recordOf({
    ...item,
    urls: { ...item.urls, 'Third-party copy': 'https://example.org/copy.tif' },
  });
  assert.deepEqual(
    record.downloads.map((download) => download.url),
    [item.urls.GeoPDF, item.urls.GeoTIFF],
  );
});

test('footprint and publication-year parsers reject impossible values', () => {
  assert.equal(publicationYear('1886-01-01'), 1886);
  assert.equal(publicationYear('n.d.'), null);
  assert.equal(publicationYear('9999'), null);
  assert.equal(footprintOf({ minX: -73, maxX: -72.75, minY: 42.25, maxY: 42.5 }).west, -73);
  assert.equal(footprintOf({ minX: 10, maxX: 9, minY: 42, maxY: 43 }), null);
  assert.equal(footprintOf({ minX: -181, maxX: 10, minY: 42, maxY: 43 }), null);
  assert.equal(footprintOf({ minX: -73, maxX: -72.75, minY: 43, maxY: 42 }), null);
});

